-- DEC-046: preserve integer-only checks for binary JSON signed/unsigned storage.
-- Known local empty tables only; no row/state rewrite. Refuse already-applied/unknown target.
SET NAMES utf8mb4;
SET SESSION lock_wait_timeout=10;
CREATE TEMPORARY TABLE seckill_json_integer_guard(ok TINYINT NOT NULL CHECK(ok=1));
INSERT INTO seckill_json_integer_guard SELECT IF(@@hostname='QIANG' AND VERSION() LIKE '8.0.%' AND DATABASE()='qinghe_promotion' AND (SELECT COUNT(*) FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN('ck_seckill_outbox_payload','ck_seckill_pool_return_snapshot','ck_seckill_clearing_snapshot') AND CHECK_CLAUSE NOT LIKE '%UNSIGNED INTEGER%')=3 AND (SELECT COUNT(*) FROM `promotion_seckill_outbox`)=0 AND (SELECT COUNT(*) FROM `promotion_seckill_pool_return`)=0 AND (SELECT COUNT(*) FROM `promotion_seckill_clearing_pool`)=0,1,0);
ALTER TABLE `promotion_seckill_outbox` DROP CHECK `ck_seckill_outbox_payload`, ADD CONSTRAINT `ck_seckill_outbox_payload` CHECK(((json_type(`payload`) = _utf8mb4'OBJECT') and (json_length(`payload`) = 4) and json_contains_path(`payload`,_utf8mb4'all',_utf8mb4'$.schemaVersion',_utf8mb4'$.tenantId',_utf8mb4'$.requestNo',_utf8mb4'$.aggregateVersion') and (json_type(json_extract(`payload`,_utf8mb4'$.schemaVersion')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.schemaVersion') = 1) and (json_type(json_extract(`payload`,_utf8mb4'$.tenantId')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.tenantId') = `tenant_id`) and (json_type(json_extract(`payload`,_utf8mb4'$.requestNo')) = _utf8mb4'STRING') and (json_unquote(json_extract(`payload`,_utf8mb4'$.requestNo')) = `request_no`) and (json_type(json_extract(`payload`,_utf8mb4'$.aggregateVersion')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.aggregateVersion') = `aggregate_version`)));
ALTER TABLE `promotion_seckill_pool_return` DROP CHECK `ck_seckill_pool_return_snapshot`, ADD CONSTRAINT `ck_seckill_pool_return_snapshot` CHECK(((json_type(`allocation_snapshot`) = _utf8mb4'OBJECT') and (json_length(`allocation_snapshot`) = 8) and json_contains_path(`allocation_snapshot`,_utf8mb4'all',_utf8mb4'$.activityNo',_utf8mb4'$.generation',_utf8mb4'$.operationNo',_utf8mb4'$.spuId',_utf8mb4'$.skuId',_utf8mb4'$.spuVersion',_utf8mb4'$.skuVersion',_utf8mb4'$.quantity') and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.activityNo')) = _utf8mb4'STRING') and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.operationNo')) = _utf8mb4'STRING') and (json_unquote(json_extract(`allocation_snapshot`,_utf8mb4'$.operationNo')) = `allocation_operation_no`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.generation')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.generation') = `generation`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.skuId')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.skuId') = `sku_id`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.quantity')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.quantity') >= `target_returned`)));
ALTER TABLE `promotion_seckill_clearing_pool` DROP CHECK `ck_seckill_clearing_snapshot`, ADD CONSTRAINT `ck_seckill_clearing_snapshot` CHECK(((json_type(`allocation_snapshot`) = _utf8mb4'OBJECT') and (json_length(`allocation_snapshot`) = 8) and json_contains_path(`allocation_snapshot`,_utf8mb4'all',_utf8mb4'$.activityNo',_utf8mb4'$.generation',_utf8mb4'$.operationNo',_utf8mb4'$.spuId',_utf8mb4'$.skuId',_utf8mb4'$.spuVersion',_utf8mb4'$.skuVersion',_utf8mb4'$.quantity') and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.generation')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.generation') = `generation`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.skuId')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.skuId') = `sku_id`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.quantity')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`allocation_snapshot`,_utf8mb4'$.quantity') = `allocated_quantity`) and (json_type(json_extract(`allocation_snapshot`,_utf8mb4'$.operationNo')) = _utf8mb4'STRING') and (json_unquote(json_extract(`allocation_snapshot`,_utf8mb4'$.operationNo')) = `allocation_operation_no`)));
SELECT 'SECKILL_JSON_INTEGER_COMPATIBILITY_READY' AS result;
